def subtract(a, b):
    # Filter out empty intervals and convert to tuples for processing
    a_intervals = sorted([tuple(interval) for interval in a if interval[0] < interval[1]])
    b_intervals = sorted([tuple(interval) for interval in b if interval[0] < interval[1]])

    # If no intervals in a, return empty
    if not a_intervals:
        return []

    # Merge overlapping/touching intervals in a
    merged_a = []
    for start, end in a_intervals:
        if merged_a and merged_a[-1][1] >= start:
            # Merge with previous interval
            merged_a[-1] = (merged_a[-1][0], max(merged_a[-1][1], end))
        else:
            merged_a.append((start, end))

    # Merge overlapping/touching intervals in b
    merged_b = []
    for start, end in b_intervals:
        if merged_b and merged_b[-1][1] >= start:
            # Merge with previous interval
            merged_b[-1] = (merged_b[-1][0], max(merged_b[-1][1], end))
        else:
            merged_b.append((start, end))

    # Subtract b from a
    result = []
    for a_start, a_end in merged_a:
        current_ranges = [(a_start, a_end)]

        for b_start, b_end in merged_b:
            new_ranges = []
            for c_start, c_end in current_ranges:
                # No overlap
                if c_end <= b_start or c_start >= b_end:
                    new_ranges.append((c_start, c_end))
                else:
                    # There is overlap, keep parts that don't overlap
                    if c_start < b_start:
                        new_ranges.append((c_start, b_start))
                    if c_end > b_end:
                        new_ranges.append((b_end, c_end))
            current_ranges = new_ranges

        result.extend(current_ranges)

    # Sort result and merge touching intervals
    result.sort()
    merged_result = []
    for start, end in result:
        if merged_result and merged_result[-1][1] >= start:
            merged_result[-1] = (merged_result[-1][0], max(merged_result[-1][1], end))
        else:
            merged_result.append((start, end))

    return [list(interval) for interval in merged_result]

